package com.tarmedtar.screendoodle;
import android.app.Service;import android.content.Intent;import android.graphics.*;import android.os.IBinder;import android.view.*;import android.widget.*;import java.util.ArrayList;
public class DrawingOverlayService extends Service{WindowManager wm;DrawView canvas;LinearLayout bar;WindowManager.LayoutParams cp;int color=Color.RED;float width=8;public IBinder onBind(Intent i){return null;}public void onCreate(){super.onCreate();wm=(WindowManager)getSystemService(WINDOW_SERVICE);canvas=new DrawView();cp=new WindowManager.LayoutParams(-1,-1,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);cp.gravity=Gravity.TOP|Gravity.START;wm.addView(canvas,cp);bar=new LinearLayout(this);bar.setBackgroundColor(0xEE222222);add("رسم",()->mode(true));add("تفاعل",()->mode(false));add("أحمر",()->color=Color.RED);add("أزرق",()->color=Color.BLUE);add("أسود",()->color=Color.BLACK);add("ممحاة",()->{color=Color.WHITE;width=28;});add("سُمك+",()->width=Math.min(30,width+3));add("مسح",()->canvas.clear());add("إخفاء",()->canvas.setVisibility(View.GONE));add("إظهار",()->canvas.setVisibility(View.VISIBLE));WindowManager.LayoutParams bp=new WindowManager.LayoutParams(-2,-2,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);bp.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;wm.addView(bar,bp);mode(true);}void add(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextSize(10);b.setPadding(5,0,5,0);b.setOnClickListener(v->r.run());bar.addView(b,new LinearLayout.LayoutParams(-2,50));}void mode(boolean draw){cp.flags=WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|(draw?0:WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE);wm.updateViewLayout(canvas,cp);}public void onDestroy(){if(canvas!=null)wm.removeView(canvas);if(bar!=null)wm.removeView(bar);super.onDestroy();}class DrawView extends View{ArrayList<Path> paths=new ArrayList<>();ArrayList<Integer> cs=new ArrayList<>();ArrayList<Float> ws=new ArrayList<>();Path cur;Paint p=new Paint(3);DrawView(){super(DrawingOverlayService.this);}protected void onDraw(Canvas c){for(int i=0;i<paths.size();i++)draw(c,paths.get(i),cs.get(i),ws.get(i));if(cur!=null)draw(c,cur,color,width);}void draw(Canvas c,Path x,int co,float w){p.setColor(co);p.setStrokeWidth(w);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);c.drawPath(x,p);}public boolean onTouchEvent(android.view.MotionEvent e){float x=e.getX(),y=e.getY();if(e.getAction()==0){cur=new Path();cur.moveTo(x,y);return true;}if(e.getAction()==2||e.getAction()==1){cur.lineTo(x,y);if(e.getAction()==1){paths.add(cur);cs.add(color);ws.add(width);cur=null;}invalidate();return true;}return true;}void clear(){paths.clear();cs.clear();ws.clear();cur=null;invalidate();}}}